Definition hipB_words_exit (ra sp gp tp t0 t1 t3 t4 t6 s0 s1 s2 s3 s5 s8 s9 s11 a3 a4 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (S Dd wpl D dn : Z) : machine_state -> Prop :=
  fun ms' => exists (t2' a0' a2' a5' a6' a7' s6' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2' s0 s1 a0' (Z_to_bv 64 (Dd + -4 * (wpl - 1))) a2' a3 a4 a5' a6' a7'
                  s2 s3 (Z_to_bv 64 (S + -4 * (wpl - 1))) s5 s6' (Z_to_bv 64 (S + -4 * (wpl - 1))) s8 s9 (Z_to_bv 64 (Dd + -4 * (wpl - 1))) s11 t3 t4 (Z_to_bv 64 0) t6)
             F (Z_to_bv 64 0x13a9f0) fc None m' (seg_rom asegs)
    /\ munch [(D, D + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma hipB_words : forall (k : nat) (j : Z)
    (ra sp gp tp t2 t3 t4 t6 s0 s1 s3 s8' s9 a0 a2 a3 a4 a5 a6 a7 s6 : word) F fc (m : mem) (R S Dd wpl shift D dn : Z),
  Z.of_nat k = wpl - 1 - j -> 0 <= j -> (1 <= k)%nat -> wpl <= 626 -> 1 <= shift <= 31 ->
  0 < D -> D mod 4 = 0 -> D + dn <= 2^47 -> (R + S) mod 4 = 0 -> (R + Dd) mod 4 = 0 ->
  D <= R + S + -4 * (wpl - 1) -> R + S + 4 <= D + dn -> D <= R + Dd + -4 * (wpl - 1) -> R + Dd + 4 <= D + dn ->
  (D + dn <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  wr_at asegs m D dn -> acc asegs m D dn -> mem_inv asegs m ->
  evt asegs (hipB_words_exit ra sp gp tp (Z_to_bv 64 0) (Z_to_bv 64 2147450880) t3 t4 t6 s0 s1 (Z_to_bv 64 R) s3 (Z_to_bv 64 shift) (Z_to_bv 64 5) s9 (Z_to_bv 64 4) a3 a4 F fc m S Dd wpl D dn)
    (MS (mkR ra sp gp tp (Z_to_bv 64 0) (Z_to_bv 64 2147450880) t2 s0 s1 a0 (Z_to_bv 64 (Dd + -4 * j)) a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 R) s3 (Z_to_bv 64 (S + -4 * j)) (Z_to_bv 64 shift) s6 (Z_to_bv 64 (S + -4 * j)) (Z_to_bv 64 5) s9 (Z_to_bv 64 (Dd + -4 * j)) (Z_to_bv 64 4)
             t3 t4 (Z_to_bv 64 (j - (wpl - 1))) t6)
        F (Z_to_bv 64 0x13a75c) fc None m (seg_rom asegs)).
Proof.
