Lemma hipB_rows : forall (k : nat) (i : Z) (gp tp t0 t2 t3 t5 s0 s1 s2 s4 s6 s7 s10 a0 a1 a2 a5 a6 a7 : word) F fc (m : mem) (FP data wpl pixh shift D dn : Z),
  Z.of_nat k = pixh - i -> 0 <= i -> (1 <= k)%nat -> pixh <= 20000 -> 1 <= wpl <= 626 -> 1 <= shift <= 31 ->
  8 <= D -> D mod 4 = 0 -> D + dn <= 2^47 -> data mod 4 = 0 -> D <= data -> data + 4 * (wpl * pixh) <= D + dn ->
  (D + dn <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  0 < FP -> FP mod 16 = 0 -> FP + 320 <= 2^47 -> (D + dn <= FP \/ FP + 320 <= D) -> 17594333495296 <= FP ->
  rw_cells asegs m (FP + 8) [C8 (Z_to_bv 64 (1 - wpl))] ->
  rw_cells asegs m (FP + 56) [C8 (Z_to_bv 64 (data + 4 * wpl + -4)); C8 (Z_to_bv 64 (data + 4 * wpl + -4))] ->
  rw_cells asegs m (FP + 96) [C8 (Z_to_bv 64 (239680 + shift * 4)); C8 (Z_to_bv 64 239680); C8 (Z_to_bv 64 (shift * 4))] ->
  rw_cells asegs m (FP + 136) [C8 (Z_to_bv 64 (wpl + -1)); C8 (Z_to_bv 64 (4 * wpl + -4)); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 (wpl + -1));
                               C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)] ->
  rw_cells asegs m (FP + 200) [C8 (Z_to_bv 64 wpl); C8 (Z_to_bv 64 pixh)] ->
  wr_at asegs m D dn -> acc asegs m D dn -> acc asegs m 239680 132 -> mem_inv asegs m ->
  evt asegs (hipB_rows_exit (Z_to_bv 64 FP) gp tp F fc m D dn)
    (MS (mkR (Z_to_bv 64 (4 * wpl + -4)) (Z_to_bv 64 FP) gp tp t0 (Z_to_bv 64 2147450880) t2 s0 s1
             a0 a1 a2 (Z_to_bv 64 wpl) (Z_to_bv 64 i) a5 a6 a7
             s2 (Z_to_bv 64 (wpl * i)) s4 (Z_to_bv 64 shift) s6 s7 (Z_to_bv 64 5) (Z_to_bv 64 shift) s10 (Z_to_bv 64 4)
             t3 (Z_to_bv 64 0) t5 (Z_to_bv 64 data))
        F (Z_to_bv 64 0x13a67c) fc None m (seg_rom asegs)).
Proof.
